input.newString:
const existing = (await listEncountersForCampaign(campaign.Id)).find((e) => e.Id === req.params.encounterId);
if (!existing) { res.status(404).json({ error: 'No such Encounter.' }); return; }

for (const p of existing.Participants) {
  if (p.Kind !== 'PC' || !p.RefId) continue;
  const sheet = await getSheet(p.RefId);
  if (!sheet) continue;
  if (sheet.Strain.some((s) => s)) {
    sheet.Stain = sheet.Strain.map(() => false);
    await saveSheet(sheet, campaign.Id);
  }
}

const encounter: Encounter = {
  ...existing,
  Status: 'Ended',
  History: [{ Id: newId('ch'), At: nowIso(), Text: 'Combat ended.' }, ...existing.History],
};
await saveEncounter(encounter);
res.json({ encounter });

